?><!doctype html><html lang="<?= sanitize(get_current_lang()) ?>" dir="<?= get_current_dir() ?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= __t('Two-step verification','تأیید دو مرحله‌ای','دوه پړاوه تایید') ?></title><link rel="stylesheet" href="<?= BASE_URL ?>assets/css/style.css"><link rel="stylesheet" href="<?= BASE_URL ?>assets/css/workflow.css"><main class="card modern-form" style="max-width:460px;margin:8vh auto"><h1><?= __t('Google Authenticator','تأییدکنندهٔ گوگل','د ګوګل تایید') ?></h1><p><?= __t('Enter the six-digit code from your authenticator app.','کُد شش‌رقمی برنامهٔ تأییدکنندهٔ خود را بنویسید.','د تایید اپ شپږ شمېریز کوډ ولیکئ.') ?></p><?php if(!totp_secret((int)$u['id'])):?><p role="alert"><?= __t('Authenticator setup is required in Settings → Account security.','تنظیم تأییدکننده از تنظیمات ← امنیت حساب لازم است.','د حساب له تنظیماتو تایید فعال کړئ.') ?></p><?php endif; ?><?php if($error):?><div class="alert alert-danger" role="alert"><?= sanitize($error) ?></div><?php endif; ?><form method="post"><?= csrf_field() ?><input type="hidden" name="next" value="<?= sanitize($next) ?>"><label for="code"><?= __t('Verification code','کُد تأیید','د تایید کوډ') ?></label><input id="code" name="code" class="form-control" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required autofocus><label style="display:flex;gap:8px;align-items:center;margin:14px 0"><input type="checkbox" name="trust_device" value="1"> <span><?= __t('Trust this device for 30 days','این دستگاه برای ۳۰ روز مورد اعتماد باشد','دا وسیله د ۳۰ ورځو لپاره باوري وي') ?></span></label><button type="submit" class="btn btn-primary"><?= __t('Verify','تأیید','تایید') ?></button></form><p><small><?= __t('Only choose this on your own phone or computer. Password changes and authenticator resets revoke trusted devices.','این گزینه را فقط روی گوشی یا کمپیوتر خودتان انتخاب کنید. تغییر رمز و بازنشانی تأییدکننده، دستگاه‌ه